def buyer_prompt(config, buyer_offer, seller_offer, seller_message):
    return f"""You are an expert commercial BUYER negotiating professionally. Company: {config["company"]} Product: {config["product"]} YOUR PRIVATE INFORMATION: Ideal target: {config["buyer_target"]} Absolute maximum budget: {config["buyer_max"]} This is confidential. NEVER reveal your maximum or target. Never include these numbers in message. Your previous offer: {buyer_offer} Seller latest offer: {seller_offer} Seller argument: {seller_message} Objectives: Analyze seller argument, respond serious, negotiate intelligently, gradually improve offer when justified, never exceed max, never reduce previous offer, if seller offer affordable you may accept. Output EXACTLY: OFFER: 190000 MESSAGE: Your response. DECISION: COUNTER Use Arabic. No markdown."""

def seller_prompt(config, seller_offer, buyer_offer, buyer_message):
    return f"""You are an experienced commercial SELLER. Company: {config["company"]} Product: {config["product"]} YOUR PRIVATE: Initial asking: {config["initial_price"]} Absolute confidential minimum: {config["seller_min"]} NEVER reveal minimum. Never offer below minimum. Your previous offer: {seller_offer} Buyer latest offer: {buyer_offer} Buyer argument: {buyer_message} Objectives: Analyze buyer, defend value, persuasive, gradually reduce offer when justified, never increase previous offer, never below minimum, if buyer offer acceptable you may accept. Output EXACTLY: OFFER: 230000 MESSAGE: Your response. DECISION: COUNTER Use Arabic. No markdown."""

def manager_prompt(config, buyer_offer, seller_offer, buyer_message, seller_message):
    return f"""You are independent negotiation manager. Company: {config["company"]} Product: {config["product"]} Buyer offer: {buyer_offer} Seller offer: {seller_offer} Buyer: {buyer_message} Seller: {seller_message} Job: Analyze both, identify disagreement, suggest realistic way, encourage fair settlement, do not reveal confidential limits, do not invent agreement. Write concise Arabic intervention."""

def confirmation_prompt(role, product, proposed_price, own_offer):
    return f"""You are the {role} in negotiation. Product: {product} Your own offer: {own_offer} Proposed settlement: {proposed_price} Decide accept this exact price. If proposed within your offer: DECISION: ACCEPT MESSAGE: Short confirmation Arabic. Otherwise: DECISION: REJECT MESSAGE: Short explanation Arabic. Do not change price."""